import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { Edit2, Trash2, Calendar, CheckCircle2, Circle, AlertCircle, TrendingUp, TrendingDown, Activity, Quote, Target } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'bg-white/80 text-red-600 border-red-200',
      accent: 'bg-red-50/50 border-red-500 text-red-900',
      icon: <TrendingUp className="w-3.5 h-3.5" />
    };
    case '看跌': return {
      color: 'bg-white/80 text-green-600 border-green-200',
      accent: 'bg-green-50/50 border-green-500 text-green-900',
      icon: <TrendingDown className="w-3.5 h-3.5" />
    };
    case '震荡': return {
      color: 'bg-white/80 text-blue-600 border-blue-200', // 修正：边框颜色改为蓝色
      accent: 'bg-blue-50/50 border-blue-500 text-blue-900',
      icon: <Activity className="w-3.5 h-3.5" />
    };
    default: return {
      color: 'bg-white/80 text-gray-500 border-gray-200',
      accent: 'bg-gray-50/50 border-gray-400 text-gray-900',
      icon: <Circle className="w-3.5 h-3.5" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const completionStatus = insight.completionStatus;
  const { color, icon, accent } = getAssetStatusStyle(insight.status);

  const getCardStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-emerald-50/40 border-emerald-100 shadow-sm';
      case '已失效': return 'bg-slate-100/40 border-slate-200 shadow-none opacity-80 grayscale-[0.3]';
      default: return 'bg-white border-gray-100 shadow-sm hover:shadow-xl hover:-translate-y-1';
    }
  };

  const getTagStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-emerald-500 text-white';
      case '已失效': return 'bg-slate-400 text-white';
      default: return 'bg-sky-500 text-white';
    }
  };

  const getStatusIcon = () => {
    switch (completionStatus) {
      case '已完成': return <CheckCircle2 className="w-3 h-3" />;
      case '已失效': return <AlertCircle className="w-3 h-3" />;
      default: return <Circle className="w-3 h-3" />;
    }
  };

  return (
    <div className={`group relative border rounded-[2rem] p-6 transition-all duration-500 flex flex-col h-full ${getCardStyle()}`}>
      {/* 顶部状态标记 */}
      <div className="absolute -top-3 left-6 flex gap-2">
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider shadow-lg transition-all active:scale-90 hover:brightness-110 ${getTagStyle()}`}
          title="点击切换状态"
        >
          {getStatusIcon()}
          {completionStatus}
        </button>
      </div>

      <div className="flex justify-between items-start mb-4 gap-3 pt-2">
        <div className="flex-grow">
          <h3 className="text-2xl font-black text-gray-900 tracking-tight mb-1">{insight.symbol}</h3>
          <div className="flex items-center text-[10px] text-gray-400 gap-1.5 font-bold">
            <Calendar className="w-3 h-3 opacity-60" />
            {date}
          </div>
        </div>
        <div className={`px-3 py-1.5 rounded-xl text-[11px] font-black border flex items-center justify-center gap-2 shrink-0 min-w-[80px] shadow-sm ${color}`}>
          {insight.status}
          {icon}
        </div>
      </div>

      <div className="space-y-4 flex-grow">
        {/* 核心观察 */}
        <div className={`p-4 rounded-2xl border transition-colors ${
          completionStatus === '已完成' ? 'bg-white/60 border-emerald-100/50' : completionStatus === '已失效' ? 'bg-white/40 border-slate-100/50' : 'bg-gray-50/50 border-gray-100'
        }`}>
          <div className="flex items-center gap-2 mb-2">
            <div className={`w-1 h-3 rounded-full ${completionStatus === '已完成' ? 'bg-emerald-400' : completionStatus === '已失效' ? 'bg-slate-300' : 'bg-gray-300'}`}></div>
            <p className={`text-[10px] font-black uppercase tracking-widest ${
              completionStatus === '已完成' ? 'text-emerald-500' : completionStatus === '已失效' ? 'text-slate-400' : 'text-gray-400'
            }`}>核心观察</p>
          </div>
          <p className={`text-sm leading-relaxed font-medium line-clamp-4 ${completionStatus === '已失效' ? 'text-slate-500 italic' : 'text-gray-700'}`}>
            {insight.focusPoints}
          </p>
        </div>

        {/* 入场点位 */}
        {insight.entryLevel && (
          <div className={`flex items-center justify-between p-3 px-4 rounded-2xl border border-dashed ${
            completionStatus === '已完成' ? 'bg-emerald-500/5 border-emerald-200' : completionStatus === '已失效' ? 'bg-slate-500/5 border-slate-200' : 'bg-gray-500/5 border-gray-200'
          }`}>
            <div className="flex flex-col">
              <p className={`text-[11px] font-black uppercase tracking-widest ${
                completionStatus === '已完成' ? 'text-emerald-600' : completionStatus === '已失效' ? 'text-slate-500' : 'text-gray-500'
              }`}>入场点位</p>
            </div>
            <div className="flex items-center gap-2">
              <Target className={`w-3 h-3 ${completionStatus === '已完成' ? 'text-emerald-400' : 'text-gray-300'}`} />
              <p className={`text-lg font-black tracking-tighter ${
                completionStatus === '已完成' ? 'text-emerald-700' : completionStatus === '已失效' ? 'text-slate-700' : 'text-gray-900'
              }`}>{insight.entryLevel}</p>
            </div>
          </div>
        )}

        {/* 交易策略 */}
        <div className="relative group/strategy">
          <div className={`p-5 rounded-2xl border-l-[6px] transition-all duration-300 ${
            completionStatus === '已失效' 
              ? 'bg-slate-50 border-slate-300' 
              : completionStatus === '已完成'
              ? 'bg-emerald-50/60 border-emerald-400'
              : `${accent}`
          }`}>
            <div className="flex items-center justify-between mb-2">
              <p className={`text-[10px] font-black uppercase tracking-[0.2em] ${
                completionStatus === '已失效' ? 'text-slate-400' : 'opacity-60'
              }`}>交易策略</p>
              <Quote className={`w-3 h-3 rotate-180 opacity-20`} />
            </div>
            <p className={`text-[13px] font-bold leading-relaxed ${
              completionStatus === '已失效' ? 'text-slate-500 italic' : 'text-gray-900'
            }`}>
              {insight.strategy}
            </p>
          </div>
        </div>
      </div>

      <div className="mt-6 pt-5 border-t border-gray-100/60 flex justify-end items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-300 transform translate-y-2 group-hover:translate-y-0">
        <button 
          onClick={() => onEdit(insight)}
          className="p-2.5 text-gray-400 hover:text-gray-900 hover:bg-gray-50 rounded-xl transition-colors flex items-center gap-2 text-[11px] font-black"
        >
          <Edit2 className="w-3.5 h-3.5" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="p-2.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-colors flex items-center gap-2 text-[11px] font-black"
        >
          <Trash2 className="w-3.5 h-3.5" />
          删除
        </button>
      </div>
    </div>
  );
};

export default MarketCard;

import { GoogleGenAI } from "@google/genai";
import { MarketInsight } from "../types";

export const generateMarketSummary = async (insights: MarketInsight[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    你是一个资深的专业市场分析师。请根据以下我记录的市场分析条目，为我提供一份简短的、专业的情绪总结和策略建议（约200字以内）。

    记录内容：
    ${insights.map(i => `- ${i.symbol} (${i.category}, ${i.status}): ${i.focusPoints}. 策略: ${i.strategy}`).join('\n')}

    请以专业的金融口吻回答，涵盖：
    1. 当前整体市场情绪分布。
    2. 核心风险点或机会点。
    3. 整体仓位管理建议。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("AI Summary Error:", error);
    return "暂时无法生成 AI 总结，请检查 API 配置或网络。";
  }
};

import React from 'react';
import { MarketInsight } from '../types';
import { TrendingUp, TrendingDown, Activity, Sparkles } from 'lucide-react';

interface MarketDashboardProps {
  insights: MarketInsight[];
  onGenerateAI: () => void;
  isGeneratingAI: boolean;
  aiSummary: string;
}

const MarketDashboard: React.FC<MarketDashboardProps> = ({ insights, onGenerateAI, isGeneratingAI, aiSummary }) => {
  const total = insights.length;
  const counts = {
    '看涨': insights.filter(i => i.status === '看涨').length,
    '看跌': insights.filter(i => i.status === '看跌').length,
    '震荡': insights.filter(i => i.status === '震荡').length,
  };

  const getPercent = (count: number) => (total > 0 ? (count / total) * 100 : 0);

  return (
    <div className="mb-12 space-y-6">
      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm flex flex-col md:flex-row gap-8 items-center">
        {/* 情绪分布 */}
        <div className="flex-1 w-full">
          <div className="flex justify-between items-end mb-4">
            <div>
              <h4 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-1">情绪分布 · Sentiment</h4>
              <p className="text-2xl font-black text-gray-900">市场倾向</p>
            </div>
            <div className="flex gap-4">
              <span className="flex items-center gap-1.5 text-xs font-black text-red-600">
                <TrendingUp className="w-3.5 h-3.5" /> {counts['看涨']}
              </span>
              <span className="flex items-center gap-1.5 text-xs font-black text-green-600">
                <TrendingDown className="w-3.5 h-3.5" /> {counts['看跌']}
              </span>
              <span className="flex items-center gap-1.5 text-xs font-black text-blue-600">
                <Activity className="w-3.5 h-3.5" /> {counts['震荡']}
              </span>
            </div>
          </div>

          <div className="h-3 w-full bg-gray-100 rounded-full flex overflow-hidden">
            <div style={{ width: `${getPercent(counts['看涨'])}%` }} className="bg-red-500 transition-all duration-1000" />
            <div style={{ width: `${getPercent(counts['震荡'])}%` }} className="bg-blue-500 transition-all duration-1000" />
            <div style={{ width: `${getPercent(counts['看跌'])}%` }} className="bg-green-500 transition-all duration-1000" />
          </div>
        </div>

        {/* AI 按钮 */}
        <div className="shrink-0">
          <button 
            onClick={onGenerateAI}
            disabled={isGeneratingAI || total === 0}
            className="flex items-center gap-3 px-8 py-4 bg-gray-900 text-white rounded-2xl font-black text-sm hover:bg-black transition-all shadow-xl shadow-gray-200 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed group"
          >
            <Sparkles className={`w-4 h-4 text-amber-400 ${isGeneratingAI ? 'animate-spin' : 'group-hover:animate-bounce'}`} />
            {isGeneratingAI ? 'AI 深度分析中...' : '生成 AI 市场综述'}
          </button>
        </div>
      </div>

      {/* AI 总结展示区 */}
