              <h3 className="text-2xl font-black text-gray-900 mb-3">暂无记录</h3>
              <p className="text-sm text-gray-400 mb-10">切换分类或重置筛选条件。</p>
            </div>
          )}

          {archivedItems.length > 0 && (
            <div className="mt-32 space-y-12">
               <div className="flex items-center gap-5 border-t border-gray-100 pt-20 mb-10">
                  <Archive className="w-6 h-6 text-gray-300" />
                  <h3 className="text-xl font-black text-gray-400">已归档历史</h3>
               </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { if(isAdmin) { setEditingInsight(i); setShowForm(true); } }}
                    onDelete={isAdmin ? handleDeleteInsight : () => {}}
                    onToggleStatus={isAdmin ? handleToggleStatus : undefined}
                    isAdmin={isAdmin}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto border-t border-gray-100 py-16 bg-white text-center">
          <p className="text-[11px] text-gray-300 font-black uppercase tracking-[0.5em]">Trading Journal Pro · EST. 2025</p>
      </footer>

      {showForm && isAdmin && (
        <InsightForm 
          initialData={editingInsight}
